window.OPUS_PAGES = window.OPUS_PAGES || {};
window.OPUS_PAGES["060"] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>QUANTA Terminal — Simulated Market</title>\n<meta name=\"description\" content=\"A dark, premium trading terminal with fictional instruments and a simulated market: live candlestick chart with pan, zoom and crosshair, flickering order book, trade feed, watchlist sparklines, portfolio donut and an order ticket.\">\n<meta name=\"theme-color\" content=\"#0b0e11\">\n<style>\n:root{\n  --bg:#0b0e11;\n  --panel:#12161c;\n  --panel-2:#171c24;\n  --panel-3:#1d232d;\n  --hair:rgba(255,255,255,.07);\n  --hair-2:rgba(255,255,255,.12);\n  --text:#e7e9ec;\n  --text-2:#98a1ad;\n  --text-3:#626c78;\n  --up:#16c784;\n  --down:#ea3943;\n  --gold:#f0b90b;\n  --gold-2:#ffd45e;\n  --sans:-apple-system,BlinkMacSystemFont,\"Segoe UI\",\"SF Pro Text\",Roboto,\"Helvetica Neue\",Arial,\"Nimbus Sans\",sans-serif;\n  --mono:\"SF Mono\",\"JetBrains Mono\",Menlo,Consolas,\"Liberation Mono\",\"DejaVu Sans Mono\",monospace;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;overflow-x:clip}\nbody{\n  margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);font-size:13px;line-height:1.4;\n  font-variant-numeric:tabular-nums;-webkit-font-smoothing:antialiased;\n}\n.sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}\nbutton,input{font:inherit;color:inherit}\n:focus-visible{outline:2px solid var(--gold);outline-offset:2px}\n.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}\n.up{color:var(--up)} .down{color:var(--down)}\n\n/* ——— top bar ——— */\n.top{\n  height:48px;display:flex;align-items:center;gap:18px;padding:0 14px;\n  border-bottom:1px solid var(--hair);background:linear-gradient(180deg,#0f1317,#0b0e11);\n}\n.logo{display:flex;align-items:center;gap:10px;font-weight:700;letter-spacing:.22em;font-size:14px}\n.logo small{font-weight:500;letter-spacing:.04em;color:var(--text-2);font-size:12.5px}\n.nav{display:flex;gap:2px}\n.nav span{padding:6px 10px;border-radius:4px;color:var(--text-2);font-size:13px}\n.nav span.on{color:var(--text);background:var(--panel-2)}\n.sim{\n  display:inline-flex;align-items:center;gap:7px;padding:4px 10px;border-radius:999px;\n  background:rgba(240,185,11,.1);border:1px solid rgba(240,185,11,.35);color:var(--gold-2);font-size:12px;font-weight:600;letter-spacing:.03em;\n}\n.sim i{width:7px;height:7px;border-radius:50%;background:var(--gold);box-shadow:0 0 0 0 rgba(240,185,11,.6);animation:ping 1.8s ease-out infinite}\n@keyframes ping{70%{box-shadow:0 0 0 7px rgba(240,185,11,0)}100%{box-shadow:0 0 0 0 rgba(240,185,11,0)}}\n.top-right{margin-left:auto;display:flex;align-items:center;gap:18px;color:var(--text-2);font-size:12.5px}\n.equity b{color:var(--text);font-family:var(--mono);font-weight:600;margin-left:6px}\n.clock{font-family:var(--mono);color:var(--text-2)}\n\n/* ——— ticker tape ——— */\n.tape{height:32px;overflow:hidden;border-bottom:1px solid var(--hair);background:#0d1115;position:relative}\n.tape::before,.tape::after{content:\"\";position:absolute;top:0;bottom:0;width:48px;z-index:2;pointer-events:none}\n.tape::before{left:0;background:linear-gradient(90deg,#0d1115,transparent)}\n.tape::after{right:0;background:linear-gradient(270deg,#0d1115,transparent)}\n.tape-track{display:flex;width:max-content;height:100%;align-items:center;animation:tape 70s linear infinite;will-change:transform}\n.tape:hover .tape-track{animation-play-state:paused}\n@keyframes tape{to{transform:translate3d(-50%,0,0)}}\n.tk{display:inline-flex;align-items:center;gap:8px;padding:0 20px;border-right:1px solid var(--hair);white-space:nowrap;font-size:12.5px}\n.tk b{font-weight:600;letter-spacing:.04em}\n.tk .px{font-family:var(--mono);color:var(--text);border-radius:3px;padding:1px 3px}\n.tk .ch{font-family:var(--mono);font-size:12px}\n\n/* ——— mobile tabs ——— */\n.mtabs{display:none}\n\n/* ——— layout ——— */\n.app{\n  display:grid;gap:6px;padding:6px;\n  grid-template-columns:288px minmax(0,1fr) 300px;\n  grid-template-rows:minmax(0,1fr) 300px;\n  grid-template-areas:\"book chart watch\" \"port ticket trades\";\n  height:calc(100vh - 80px);min-height:760px;\n}\n.panel{\n  background:var(--panel);border:1px solid var(--hair);border-radius:8px;min-width:0;min-height:0;\n  display:flex;flex-direction:column;overflow:hidden;position:relative;\n}\n.p-book{grid-area:book}.p-chart{grid-area:chart}.p-watch{grid-area:watch}\n.p-port{grid-area:port}.p-ticket{grid-area:ticket}.p-trades{grid-area:trades}\n.ph{\n  display:flex;align-items:center;justify-content:space-between;gap:10px;\n  padding:9px 12px;border-bottom:1px solid var(--hair);min-height:38px;\n}\n.ph h2{margin:0;font-size:12px;font-weight:600;letter-spacing:.09em;text-transform:uppercase;color:var(--text-2)}\n.ph .sub{font-size:11.5px;color:var(--text-3)}\n.cols{display:grid;padding:6px 12px 4px;font-size:11px;color:var(--text-3);letter-spacing:.02em}\n\n/* order book */\n.book-cols,.brow{grid-template-columns:1.05fr 1fr 1fr}\n.cols span:not(:first-child),.brow span:not(:first-child){text-align:right}\n.book-body{flex:1;display:flex;flex-direction:column;min-height:0}\n.side{display:flex;flex-direction:column;overflow:hidden}\n.side.asks{flex:1;justify-content:flex-end}\n.side.bids{flex:1;justify-content:flex-start}\n.brow{\n  position:relative;display:grid;height:19px;align-items:center;padding:0 12px;\n  font-family:var(--mono);font-size:12px;cursor:pointer;\n}\n.brow:hover{background:rgba(255,255,255,.04)}\n.brow .bar{position:absolute;right:0;top:1px;bottom:1px;width:0;transition:width .35s ease;pointer-events:none}\n.asks .bar{background:rgba(234,57,67,.13)}\n.bids .bar{background:rgba(22,199,132,.12)}\n.asks .brow span:first-child{color:var(--down)}\n.bids .brow span:first-child{color:var(--up)}\n.brow span{position:relative}\n.brow span:nth-child(2){color:var(--text)}\n.brow span:nth-child(3){color:var(--text-2)}\n.brow.fa{animation:fla .5s ease}\n.brow.fb{animation:flb .5s ease}\n@keyframes fla{from{background:rgba(255,255,255,.1)}}\n@keyframes flb{from{background:rgba(255,255,255,.1)}}\n.spread{\n  display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 12px;\n  border-top:1px solid var(--hair);border-bottom:1px solid var(--hair);background:var(--panel-2);\n}\n.spread .last{font-family:var(--mono);font-size:19px;font-weight:600;display:flex;align-items:center;gap:6px}\n.spread .last svg{transition:transform .3s}\n.spread .last.down svg{transform:rotate(180deg)}\n.spread .sp{font-size:11.5px;color:var(--text-3);text-align:right}\n.seg{display:inline-flex;gap:2px;background:var(--bg);border:1px solid var(--hair);border-radius:5px;padding:2px}\n.seg button{appearance:none;border:0;background:transparent;border-radius:3px;padding:3px 7px;cursor:pointer;color:var(--text-2);font-size:12px;line-height:1.2}\n.seg button[aria-pressed=\"true\"]{background:var(--panel-3);color:var(--text)}\n.seg button:hover{color:var(--text)}\n.bv{display:inline-block;width:12px;height:10px;vertical-align:-1px}\n\n/* chart */\n.chart-head{display:flex;align-items:center;gap:22px;padding:10px 14px;border-bottom:1px solid var(--hair);flex-wrap:wrap;row-gap:6px}\n.pair{display:flex;align-items:center;gap:10px}\n.coin{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:11px;color:#0b0e11}\n.pair h1{margin:0;font-size:17px;font-weight:700;letter-spacing:.02em;line-height:1.1}\n.pair h1 span{color:var(--text-3);font-weight:500}\n.pair p{margin:0;font-size:11.5px;color:var(--text-3)}\n.bigpx{font-family:var(--mono);font-size:22px;font-weight:600;border-radius:4px;padding:0 4px;transition:color .3s}\n.stat{display:flex;flex-direction:column;font-size:11px;color:var(--text-3)}\n.stat b{font-family:var(--mono);font-weight:500;font-size:12.5px;color:var(--text)}\n.chart-tools{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:6px 10px;border-bottom:1px solid var(--hair);flex-wrap:wrap}\n.tf button{padding:4px 9px}\n.ma-leg{display:flex;gap:12px;font-family:var(--mono);font-size:11.5px;flex-wrap:wrap}\n.ma-leg button{appearance:none;border:0;background:none;cursor:pointer;padding:2px 0;font-family:var(--mono);font-size:11.5px}\n.ma-leg button[aria-pressed=\"false\"]{opacity:.35;text-decoration:line-through}\n.chart-box{position:relative;flex:1;min-height:0;cursor:crosshair;touch-action:none}\n.chart-box canvas{position:absolute;inset:0;display:block}\n.ohlc{position:absolute;left:10px;top:8px;display:flex;gap:10px;font-family:var(--mono);font-size:11.5px;color:var(--text-2);pointer-events:none;flex-wrap:wrap;right:80px}\n.ohlc b{font-weight:500}\n.ctip{\n  position:absolute;left:0;top:0;pointer-events:none;opacity:0;transition:opacity .15s;\n  background:rgba(23,28,36,.94);border:1px solid var(--hair-2);border-radius:6px;padding:8px 10px;min-width:150px;\n  font-family:var(--mono);font-size:11.5px;box-shadow:0 12px 28px -12px rgba(0,0,0,.8);\n}\n.ctip.show{opacity:1}\n.ctip .t{color:var(--text-3);font-family:var(--sans);margin-bottom:4px;font-size:11.5px}\n.ctip div.r{display:flex;justify-content:space-between;gap:14px;line-height:1.55}\n.ctip div.r span:first-child{color:var(--text-3)}\n.zoom{position:absolute;right:72px;bottom:30px;display:flex;gap:4px;opacity:.55;transition:opacity .2s}\n.chart-box:hover .zoom,.zoom:focus-within{opacity:1}\n.zoom button{appearance:none;width:26px;height:26px;border-radius:5px;border:1px solid var(--hair-2);background:rgba(23,28,36,.9);cursor:pointer;display:grid;place-items:center;color:var(--text-2)}\n.zoom button:hover{color:var(--text);border-color:var(--gold)}\n\n/* watchlist */\n.search{margin:0;padding:8px 12px 6px}\n.search input{width:100%;background:var(--bg);border:1px solid var(--hair);border-radius:5px;padding:6px 10px;font-size:12.5px;outline:none}\n.search input:focus{border-color:rgba(240,185,11,.6)}\n.wl{list-style:none;margin:0;padding:0 0 6px;overflow:auto;flex:1;scrollbar-width:thin;scrollbar-color:#2a313b transparent}\n.wrow{\n  display:grid;grid-template-columns:minmax(0,1fr) 64px 86px;gap:8px;align-items:center;\n  padding:6px 12px;cursor:pointer;border-left:2px solid transparent;width:100%;text-align:left;\n  appearance:none;background:none;border-top:0;border-right:0;border-bottom:0;\n}\n.wrow:hover{background:rgba(255,255,255,.03)}\n.wrow.sel{background:rgba(240,185,11,.06);border-left-color:var(--gold)}\n.wrow .s{display:flex;flex-direction:column;min-width:0}\n.wrow .s b{font-size:13px;letter-spacing:.03em}\n.wrow .s small{font-size:11px;color:var(--text-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.wrow svg{display:block;width:64px;height:26px;overflow:visible}\n.wrow .q{display:flex;flex-direction:column;align-items:flex-end;gap:2px}\n.wrow .q .px{font-family:var(--mono);font-size:12.5px;border-radius:3px;padding:0 3px}\n.pct{font-family:var(--mono);font-size:11px;padding:1px 6px;border-radius:4px;min-width:62px;text-align:center}\n.pct.up{background:rgba(22,199,132,.14)}\n.pct.down{background:rgba(234,57,67,.14)}\n\n/* flashes */\n.fu{animation:fu .7s ease}\n.fu2{animation:fu2 .7s ease}\n.fd{animation:fd .7s ease}\n.fd2{animation:fd2 .7s ease}\n@keyframes fu{from{background:rgba(22,199,132,.35);color:#7ff0c3}}\n@keyframes fu2{from{background:rgba(22,199,132,.35);color:#7ff0c3}}\n@keyframes fd{from{background:rgba(234,57,67,.35);color:#ff9aa1}}\n@keyframes fd2{from{background:rgba(234,57,67,.35);color:#ff9aa1}}\n\n/* trades */\n.tr-cols,.trow{grid-template-columns:1fr 1fr 1fr}\n.tlist{flex:1;overflow:hidden;min-height:0}\n.trow{display:grid;height:19px;align-items:center;padding:0 12px;font-family:var(--mono);font-size:12px}\n.trow span:nth-child(2){color:var(--text)}\n.trow span:nth-child(3){color:var(--text-3)}\n.trow.new{animation:tin .45s ease}\n.trow.mine{background:rgba(240,185,11,.08)}\n.trow.mine span:nth-child(3){color:var(--gold)}\n@keyframes tin{from{background:rgba(255,255,255,.09);transform:translateY(-6px);opacity:.3}}\n\n/* portfolio */\n.port-body{flex:1;display:grid;grid-template-columns:140px minmax(0,1fr);gap:14px;align-items:center;padding:10px 12px;min-height:0}\n.donut{width:140px;height:140px;display:block}\n.legend .lv{color:var(--text-3);margin-right:8px;font-size:11px}\n.donut circle.seg-arc{transition:stroke-dasharray .6s ease,stroke-dashoffset .6s ease,stroke-width .2s,opacity .2s;cursor:pointer}\n.donut circle.seg-arc.dim{opacity:.3}\n.donut text{font-family:var(--mono);fill:var(--text)}\n.legend{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:3px;font-size:12px;min-width:0}\n.legend li{display:grid;grid-template-columns:10px minmax(34px,1fr) auto;gap:8px;align-items:center;padding:2px 4px;border-radius:4px;cursor:default}\n.legend li.hl{background:rgba(255,255,255,.05)}\n.legend i{width:9px;height:9px;border-radius:2px}\n.legend .n{color:var(--text-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.legend .v{font-family:var(--mono);color:var(--text)}\n.pnl{font-family:var(--mono);font-size:11.5px;white-space:nowrap}\n\n/* ticket */\n.ticket-body{flex:1;display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:10px 14px 12px;min-height:0}\n.form{display:flex;flex-direction:column;gap:7px;min-width:0}\n.avail{display:flex;justify-content:space-between;font-size:11.5px;color:var(--text-3)}\n.avail b{font-family:var(--mono);color:var(--text-2);font-weight:500}\n.field{\n  display:flex;align-items:center;background:var(--bg);border:1px solid var(--hair);border-radius:6px;height:34px;padding:0 4px 0 10px;\n  transition:border-color .2s;\n}\n.field:focus-within{border-color:rgba(240,185,11,.7)}\n.field.bad{border-color:var(--down)}\n.field label{font-size:12px;color:var(--text-3);min-width:46px}\n.field input{flex:1;min-width:0;background:none;border:0;outline:none;text-align:right;font-family:var(--mono);font-size:13px;padding:0 6px}\n.field input:disabled{color:var(--text-3)}\n.field .unit{font-size:12px;color:var(--text-2);min-width:36px;text-align:right;padding-right:6px}\n.step-btn{appearance:none;border:0;background:none;color:var(--text-3);cursor:pointer;width:18px;height:26px;font-size:14px;line-height:1;padding:0}\n.step-btn:hover{color:var(--text)}\n.slider{position:relative;height:22px;display:flex;align-items:center}\n.slider input{appearance:none;-webkit-appearance:none;width:100%;height:4px;border-radius:4px;background:linear-gradient(90deg,var(--c,#16c784) var(--p,0%),#2a313b var(--p,0%));outline:none;margin:0;position:relative;z-index:1}\n.slider input::-webkit-slider-thumb{-webkit-appearance:none;width:14px;height:14px;border-radius:3px;background:var(--panel);border:2px solid var(--c,#16c784);transform:rotate(45deg);cursor:pointer}\n.slider input::-moz-range-thumb{width:12px;height:12px;border-radius:3px;background:var(--panel);border:2px solid var(--c,#16c784);cursor:pointer}\n.slider .ticks{position:absolute;left:0;right:0;top:50%;display:flex;justify-content:space-between;transform:translateY(-50%);pointer-events:none;padding:0 1px}\n.slider .ticks i{width:7px;height:7px;background:#2a313b;border:1px solid var(--panel);transform:rotate(45deg);border-radius:1px}\n.form .err{min-height:16px;font-size:11.5px;color:#ff8a92;margin:-2px 0 0}\n.submit{\n  appearance:none;border:0;border-radius:6px;height:38px;cursor:pointer;font-weight:700;font-size:14px;letter-spacing:.02em;color:#fff;\n  transition:filter .2s,transform .1s;\n}\n.submit:hover{filter:brightness(1.1)}\n.submit:active{transform:translateY(1px)}\n.buy .submit{background:linear-gradient(180deg,#1bd18e,#12a86f)}\n.sell .submit{background:linear-gradient(180deg,#f04a54,#c92d36)}\n.otype button{padding:3px 10px}\n\n/* toasts */\n.toasts{position:fixed;right:14px;top:88px;z-index:90;display:flex;flex-direction:column;gap:8px;width:min(340px,calc(100vw - 28px))}\n.toast{\n  position:relative;overflow:hidden;background:var(--panel-2);border:1px solid var(--hair-2);border-left:3px solid var(--up);\n  border-radius:8px;padding:11px 14px 13px;box-shadow:0 18px 40px -16px rgba(0,0,0,.8);animation:tIn .35s cubic-bezier(.2,.9,.3,1.2);\n}\n.toast.sell{border-left-color:var(--down)}\n.toast b{display:block;font-size:13px;margin-bottom:2px}\n.toast p{margin:0;font-size:12.5px;color:var(--text-2)}\n.toast .mono{color:var(--text)}\n.toast i{position:absolute;left:0;bottom:0;height:2px;background:var(--gold);animation:tBar 4.2s linear forwards}\n.toast.out{animation:tOut .3s ease forwards}\n@keyframes tIn{from{transform:translateX(30px);opacity:0}}\n@keyframes tOut{to{transform:translateX(30px);opacity:0}}\n@keyframes tBar{from{width:100%}to{width:0}}\n\n.foot{padding:6px 14px 10px;color:var(--text-3);font-size:11.5px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}\n\n/* ——— responsive ——— */\n@media (max-width:1180px){\n  .app{\n    grid-template-columns:minmax(0,1fr) 300px;grid-template-rows:auto;\n    grid-template-areas:\"chart book\" \"ticket trades\" \"watch port\";height:auto;min-height:0;\n  }\n  .p-chart{height:540px}\n  .p-book{height:540px}\n  .p-ticket,.p-trades{height:310px}\n  .p-watch{height:420px}.p-port{height:420px}\n  .port-body{grid-template-columns:1fr;justify-items:center}\n}\n@media (max-width:760px){\n  .top{gap:10px;padding:0 12px}\n  .nav,.equity{display:none}\n  .logo small{display:none}\n  .top-right{gap:10px}\n  .mtabs{\n    display:flex;position:sticky;top:0;z-index:30;background:rgba(11,14,17,.96);border-bottom:1px solid var(--hair);\n    overflow-x:auto;scrollbar-width:none;\n  }\n  .mtabs::-webkit-scrollbar{display:none}\n  .mtabs button{\n    appearance:none;flex:1 0 auto;border:0;background:none;color:var(--text-2);padding:11px 12px;font-size:13px;cursor:pointer;\n    border-bottom:2px solid transparent;\n  }\n  .mtabs button[aria-pressed=\"true\"]{color:var(--text);border-bottom-color:var(--gold)}\n  .app{display:block;padding:6px}\n  .panel{display:none}\n  .panel.m-on{display:flex}\n  .p-chart{height:calc(100vh - 150px);min-height:480px}\n  .p-book{height:auto;min-height:560px}\n  .p-trades{height:auto;min-height:560px}\n  .p-ticket{height:auto}\n  .p-watch{height:auto;min-height:520px}\n  .p-port{height:auto}\n  .ticket-body{grid-template-columns:1fr}\n  .chart-head{gap:14px;padding:10px 12px}\n  .chart-head{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px 8px}\n  .pair{grid-column:1/3}\n  .bigpx{grid-column:3/5;justify-self:end;align-self:center}\n  .stat b{font-size:12px}\n  .port-body{grid-template-columns:1fr;justify-items:center;padding:16px}\n  .donut{width:170px;height:170px}\n  .legend{width:100%}\n  .zoom{right:66px;bottom:28px;opacity:1}\n  .toasts{top:auto;bottom:14px}\n}\n@media (prefers-reduced-motion:reduce){\n  .tape-track{animation-duration:240s}\n  .sim i{animation:none}\n  .brow.fa,.brow.fb,.trow.new,.fu,.fu2,.fd,.fd2{animation:none}\n}\n</style>\n</head>\n<body>\n<header class=\"top\">\n  <div class=\"logo\">\n    <svg width=\"26\" height=\"26\" viewBox=\"0 0 26 26\" aria-hidden=\"true\">\n      <defs><linearGradient id=\"lg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffd45e\"/><stop offset=\"1\" stop-color=\"#d89a00\"/></linearGradient></defs>\n      <path d=\"M13 1.5 L23 7.25 V18.75 L13 24.5 L3 18.75 V7.25Z\" fill=\"url(#lg)\"/>\n      <circle cx=\"13\" cy=\"13\" r=\"5.2\" fill=\"none\" stroke=\"#0b0e11\" stroke-width=\"2.2\"/>\n      <path d=\"M15.6 15.6 L19 19\" stroke=\"#0b0e11\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\n    </svg>\n    QUANTA <small>Terminal</small>\n  </div>\n  <nav class=\"nav\" aria-label=\"Markets\"><span class=\"on\">Spot</span><span>Research</span><span>Wallet</span></nav>\n  <span class=\"sim\" title=\"All data on this page is simulated\"><i aria-hidden=\"true\"></i>Simulated market</span>\n  <div class=\"top-right\">\n    <span class=\"equity\">Equity <b id=\"eqTop\">—</b></span>\n    <span class=\"clock\" id=\"clock\" aria-label=\"Time, UTC\">--:--:-- UTC</span>\n  </div>\n</header>\n\n<div class=\"tape\" aria-label=\"Ticker tape, simulated prices\">\n  <div class=\"tape-track\" id=\"tape\"></div>\n</div>\n\n<div class=\"mtabs\" id=\"mtabs\" role=\"group\" aria-label=\"Panels\">\n  <button type=\"button\" data-p=\"p-chart\" aria-pressed=\"true\">Chart</button>\n  <button type=\"button\" data-p=\"p-book\" aria-pressed=\"false\">Book</button>\n  <button type=\"button\" data-p=\"p-trades\" aria-pressed=\"false\">Trades</button>\n  <button type=\"button\" data-p=\"p-ticket\" aria-pressed=\"false\">Trade</button>\n  <button type=\"button\" data-p=\"p-watch\" aria-pressed=\"false\">Markets</button>\n  <button type=\"button\" data-p=\"p-port\" aria-pressed=\"false\">Wallet</button>\n</div>\n\n<main class=\"app\" id=\"app\">\n  <!-- ORDER BOOK -->\n  <section class=\"panel p-book\" id=\"p-book\" aria-labelledby=\"bookH\">\n    <div class=\"ph\">\n      <h2 id=\"bookH\">Order book</h2>\n      <div class=\"seg\" role=\"group\" aria-label=\"Order book view\">\n        <button type=\"button\" data-bv=\"both\" aria-pressed=\"true\" aria-label=\"Bids and asks\"><svg class=\"bv\" viewBox=\"0 0 12 10\" aria-hidden=\"true\"><rect width=\"12\" height=\"4\" fill=\"#ea3943\"/><rect y=\"6\" width=\"12\" height=\"4\" fill=\"#16c784\"/></svg></button>\n        <button type=\"button\" data-bv=\"bids\" aria-pressed=\"false\" aria-label=\"Bids only\"><svg class=\"bv\" viewBox=\"0 0 12 10\" aria-hidden=\"true\"><rect width=\"12\" height=\"10\" fill=\"#16c784\"/></svg></button>\n        <button type=\"button\" data-bv=\"asks\" aria-pressed=\"false\" aria-label=\"Asks only\"><svg class=\"bv\" viewBox=\"0 0 12 10\" aria-hidden=\"true\"><rect width=\"12\" height=\"10\" fill=\"#ea3943\"/></svg></button>\n      </div>\n    </div>\n    <div class=\"cols book-cols\"><span>Price (QD)</span><span id=\"bookAmtH\">Amount</span><span>Total</span></div>\n    <div class=\"book-body\" id=\"bookBody\">\n      <div class=\"side asks\" id=\"asks\"></div>\n      <div class=\"spread\">\n        <span class=\"last\" id=\"spLast\"><svg width=\"12\" height=\"12\" viewBox=\"0 0 12 12\" aria-hidden=\"true\"><path d=\"M6 1 L11 8 H7.5 V11 H4.5 V8 H1Z\" fill=\"currentColor\"/></svg><span id=\"spLastTxt\">—</span></span>\n        <span class=\"sp\">Spread <span class=\"mono\" id=\"spVal\">—</span></span>\n      </div>\n      <div class=\"side bids\" id=\"bids\"></div>\n    </div>\n  </section>\n\n  <!-- CHART -->\n  <section class=\"panel p-chart m-on\" id=\"p-chart\" aria-label=\"Price chart\">\n    <div class=\"chart-head\">\n      <div class=\"pair\">\n        <span class=\"coin\" id=\"coin\" aria-hidden=\"true\">AX</span>\n        <div><h1 id=\"pairName\">AXLM <span>/ QD</span></h1><p id=\"pairLong\">Axolotl Mining</p></div>\n      </div>\n      <span class=\"bigpx\" id=\"bigPx\">—</span>\n      <div class=\"stat\"><span>24h change</span><b id=\"s24c\">—</b></div>\n      <div class=\"stat\"><span>24h high</span><b id=\"s24h\">—</b></div>\n      <div class=\"stat hide-m\"><span>24h low</span><b id=\"s24l\">—</b></div>\n      <div class=\"stat hide-m\"><span>24h volume</span><b id=\"s24v\">—</b></div>\n    </div>\n    <div class=\"chart-tools\">\n      <div class=\"seg tf\" role=\"group\" aria-label=\"Time range\" id=\"tfs\">\n        <button type=\"button\" data-tf=\"1\" aria-pressed=\"false\">1m</button>\n        <button type=\"button\" data-tf=\"5\" aria-pressed=\"false\">5m</button>\n        <button type=\"button\" data-tf=\"15\" aria-pressed=\"true\">15m</button>\n        <button type=\"button\" data-tf=\"60\" aria-pressed=\"false\">1H</button>\n        <button type=\"button\" data-tf=\"240\" aria-pressed=\"false\">4H</button>\n        <button type=\"button\" data-tf=\"1440\" aria-pressed=\"false\">1D</button>\n      </div>\n      <div class=\"ma-leg\" id=\"maLeg\">\n        <button type=\"button\" data-ma=\"0\" aria-pressed=\"true\" style=\"color:#f0b90b\">MA7 <span id=\"ma0\">—</span></button>\n        <button type=\"button\" data-ma=\"1\" aria-pressed=\"true\" style=\"color:#58a6ff\">MA25 <span id=\"ma1\">—</span></button>\n        <button type=\"button\" data-ma=\"2\" aria-pressed=\"true\" style=\"color:#c678dd\">MA99 <span id=\"ma2\">—</span></button>\n      </div>\n    </div>\n    <div class=\"chart-box\" id=\"chartBox\" tabindex=\"0\" role=\"application\" aria-label=\"Candlestick chart. Drag or use arrow keys to pan, scroll or plus and minus to zoom.\">\n      <canvas id=\"chart\" aria-hidden=\"true\"></canvas>\n      <div class=\"ohlc\" id=\"ohlc\" aria-hidden=\"true\"></div>\n      <div class=\"ctip\" id=\"ctip\" aria-hidden=\"true\"></div>\n      <div class=\"zoom\">\n        <button type=\"button\" id=\"zIn\" aria-label=\"Zoom in\"><svg width=\"12\" height=\"12\" viewBox=\"0 0 12 12\" aria-hidden=\"true\"><path d=\"M6 1 V11 M1 6 H11\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg></button>\n        <button type=\"button\" id=\"zOut\" aria-label=\"Zoom out\"><svg width=\"12\" height=\"12\" viewBox=\"0 0 12 12\" aria-hidden=\"true\"><path d=\"M1 6 H11\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg></button>\n        <button type=\"button\" id=\"zReset\" aria-label=\"Reset view\"><svg width=\"12\" height=\"12\" viewBox=\"0 0 12 12\" aria-hidden=\"true\"><path d=\"M10 6 A4 4 0 1 1 8.8 3.2 M9.4 1 V3.6 H6.8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/></svg></button>\n      </div>\n    </div>\n  </section>\n\n  <!-- WATCHLIST -->\n  <section class=\"panel p-watch\" id=\"p-watch\" aria-labelledby=\"wlH\">\n    <div class=\"ph\"><h2 id=\"wlH\">Watchlist</h2><span class=\"sub\">10 instruments · QD</span></div>\n    <p class=\"search\"><label class=\"sr-only\" for=\"wlSearch\">Filter instruments</label><input id=\"wlSearch\" type=\"search\" placeholder=\"Search symbol or name\" autocomplete=\"off\"></p>\n    <ul class=\"wl\" id=\"wl\"></ul>\n  </section>\n\n  <!-- PORTFOLIO -->\n  <section class=\"panel p-port\" id=\"p-port\" aria-labelledby=\"portH\">\n    <div class=\"ph\"><h2 id=\"portH\">Portfolio</h2><span class=\"pnl\" id=\"pnl\">—</span></div>\n    <p class=\"sr-only\">Today's simulated profit and loss is shown beside the heading.</p>\n    <div class=\"port-body\">\n      <svg class=\"donut\" id=\"donut\" viewBox=\"0 0 160 160\" role=\"img\" aria-label=\"Portfolio allocation donut chart\"></svg>\n      <ul class=\"legend\" id=\"legend\"></ul>\n    </div>\n  </section>\n\n  <!-- TICKET -->\n  <section class=\"panel p-ticket\" id=\"p-ticket\" aria-labelledby=\"tkH\">\n    <div class=\"ph\">\n      <h2 id=\"tkH\">Spot order</h2>\n      <div class=\"seg otype\" role=\"group\" aria-label=\"Order type\">\n        <button type=\"button\" data-ot=\"limit\" aria-pressed=\"true\">Limit</button>\n        <button type=\"button\" data-ot=\"market\" aria-pressed=\"false\">Market</button>\n      </div>\n    </div>\n    <div class=\"ticket-body\">\n      <form class=\"form buy\" id=\"fBuy\" novalidate>\n        <div class=\"avail\"><span>Available</span><b id=\"availBuy\">—</b></div>\n        <div class=\"field\" id=\"fbPriceF\"><label for=\"fbPrice\">Price</label><input id=\"fbPrice\" inputmode=\"decimal\" autocomplete=\"off\"><button type=\"button\" class=\"step-btn\" data-stp=\"fbPrice\" data-d=\"-1\" aria-label=\"Lower buy price\">−</button><button type=\"button\" class=\"step-btn\" data-stp=\"fbPrice\" data-d=\"1\" aria-label=\"Raise buy price\">+</button><span class=\"unit\">QD</span></div>\n        <div class=\"field\" id=\"fbAmtF\"><label for=\"fbAmt\">Amount</label><input id=\"fbAmt\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"0.00\"><span class=\"unit sym\">AXLM</span></div>\n        <div class=\"slider\" style=\"--c:#16c784\"><input type=\"range\" id=\"fbPct\" min=\"0\" max=\"100\" step=\"1\" value=\"0\" aria-label=\"Percent of available balance to spend\"><span class=\"ticks\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i><i></i></span></div>\n        <div class=\"field\"><label for=\"fbTot\">Total</label><input id=\"fbTot\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"0.00\"><span class=\"unit\">QD</span></div>\n        <p class=\"err\" id=\"fbErr\" role=\"alert\"></p>\n        <button type=\"submit\" class=\"submit\">Buy <span class=\"sym\">AXLM</span></button>\n      </form>\n      <form class=\"form sell\" id=\"fSell\" novalidate>\n        <div class=\"avail\"><span>Available</span><b id=\"availSell\">—</b></div>\n        <div class=\"field\" id=\"fsPriceF\"><label for=\"fsPrice\">Price</label><input id=\"fsPrice\" inputmode=\"decimal\" autocomplete=\"off\"><button type=\"button\" class=\"step-btn\" data-stp=\"fsPrice\" data-d=\"-1\" aria-label=\"Lower sell price\">−</button><button type=\"button\" class=\"step-btn\" data-stp=\"fsPrice\" data-d=\"1\" aria-label=\"Raise sell price\">+</button><span class=\"unit\">QD</span></div>\n        <div class=\"field\" id=\"fsAmtF\"><label for=\"fsAmt\">Amount</label><input id=\"fsAmt\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"0.00\"><span class=\"unit sym\">AXLM</span></div>\n        <div class=\"slider\" style=\"--c:#ea3943\"><input type=\"range\" id=\"fsPct\" min=\"0\" max=\"100\" step=\"1\" value=\"0\" aria-label=\"Percent of holdings to sell\"><span class=\"ticks\" aria-hidden=\"true\"><i></i><i></i><i></i><i></i><i></i></span></div>\n        <div class=\"field\"><label for=\"fsTot\">Total</label><input id=\"fsTot\" inputmode=\"decimal\" autocomplete=\"off\" placeholder=\"0.00\"><span class=\"unit\">QD</span></div>\n        <p class=\"err\" id=\"fsErr\" role=\"alert\"></p>\n        <button type=\"submit\" class=\"submit\">Sell <span class=\"sym\">AXLM</span></button>\n      </form>\n    </div>\n  </section>\n\n  <!-- TRADES -->\n  <section class=\"panel p-trades\" id=\"p-trades\" aria-labelledby=\"trH\">\n    <div class=\"ph\"><h2 id=\"trH\">Recent trades</h2><span class=\"sub\" id=\"trCount\">live</span></div>\n    <div class=\"cols tr-cols\"><span>Price (QD)</span><span style=\"text-align:right\" id=\"trAmtH\">Amount</span><span style=\"text-align:right\">Time</span></div>\n    <div class=\"tlist\" id=\"tlist\" aria-live=\"off\"></div>\n  </section>\n</main>\n<footer class=\"foot\">\n  <span>QUANTA is a fictional terminal. Every instrument, price, order and balance is simulated in your browser — not market data, not advice.</span>\n  <span class=\"mono\">QD = Quanta Dollars (fictional)</span>\n</footer>\n<div class=\"toasts\" id=\"toasts\" aria-live=\"polite\"></div>\n\n<script>\n(function(){\n'use strict';\n\n/* ——— utilities ——— */\nfunction $(id){return document.getElementById(id);}\nfunction mulberry(a){return function(){a|=0;a=a+0x6D2B79F5|0;var t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}\nfunction gauss(r){var u=0,v=0;while(u===0)u=r();while(v===0)v=r();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);}\nvar R=Math.random;\nvar NF={};\nfunction nf(dp){if(!NF[dp]) NF[dp]=new Intl.NumberFormat('en-US',{minimumFractionDigits:dp,maximumFractionDigits:dp});return NF[dp];}\nfunction fmt(v,dp){return nf(dp).format(v);}\nfunction compact(v){\n  if(v>=1e9) return (v/1e9).toFixed(2)+'B';\n  if(v>=1e6) return (v/1e6).toFixed(2)+'M';\n  if(v>=1e3) return (v/1e3).toFixed(1)+'K';\n  return v.toFixed(0);\n}\nfunction pct(v){return (v>=0?'+':'')+(v*100).toFixed(2)+'%';}\nfunction clamp(v,a,b){return Math.max(a,Math.min(b,v));}\nvar reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n/* ——— instruments (fictional) ——— */\nvar INST=[\n  {sym:'AXLM',name:'Axolotl Mining',p:1284.5,dp:2,step:.1,vol:.00009,col:'#f0b90b',hold:12.5},\n  {sym:'ZPHR',name:'Zephyrine Air',p:342.18,dp:2,step:.01,vol:.00011,col:'#2ec4b6',hold:40},\n  {sym:'OKLP',name:'Orbital Kelp',p:57.91,dp:3,step:.005,vol:.00014,col:'#7ee081',hold:0},\n  {sym:'LMFG',name:'Lumen Forge',p:912.4,dp:2,step:.1,vol:.00009,col:'#8b7cf6',hold:18},\n  {sym:'NMB9',name:'Nimbus Nine',p:18.736,dp:3,step:.002,vol:.00016,col:'#4aa3ff',hold:900},\n  {sym:'QZWL',name:'Quartzwell',p:4210,dp:1,step:.5,vol:.00008,col:'#ff7a59',hold:3.2},\n  {sym:'FRVA',name:'Ferrovia Rail',p:126.35,dp:2,step:.01,vol:.0001,col:'#e0a3ff',hold:0},\n  {sym:'HCGD',name:'Halcyon Grid',p:77.02,dp:2,step:.01,vol:.00012,col:'#ffc4a3',hold:0},\n  {sym:'VLTN',name:'Voltane Labs',p:2048.8,dp:2,step:.2,vol:.00011,col:'#9ad0ff',hold:0},\n  {sym:'MRRW',name:'Marrow & Pine',p:9.842,dp:3,step:.001,vol:.00015,col:'#d6c28a',hold:0}\n];\nvar ALPHA=.08,BETA=.9;\nfunction bridge(r,a,b,n,s){\n  var w=[0];for(var i=1;i<n;i++) w.push(w[i-1]+gauss(r)*s);\n  var la=Math.log(a),lb=Math.log(b),out=[];\n  for(var j=0;j<n;j++){var t=j/(n-1);out.push(Math.exp(la+(lb-la)*t+w[j]-w[n-1]*t));}\n  return out;\n}\nINST.forEach(function(m,i){\n  var r=mulberry(1000+i*77);\n  m.price=m.p;m.prev=m.p;\n  m.sig=m.vol;\n  m.open24=m.p*Math.exp(gauss(r)*.028);\n  m.high24=Math.max(m.p,m.open24)*(1+Math.abs(gauss(r))*.008+.004);\n  m.low24=Math.min(m.p,m.open24)*(1-Math.abs(gauss(r))*.008-.004);\n  m.vol24=(4e6+r()*3e7)/m.p;\n  // sparkline history: walk backwards so the line ends on the live price\n  m.spark=bridge(r,m.open24,m.p,60,.0042);m.sparkT=0;\n});\nvar sel=0;\nvar cash=48250;\n\n/* ——— GARCH-style tick ——— */\nfunction stepPrice(m){\n  var z=gauss(R);\n  var eps=m.sig*z;\n  var omega=m.vol*m.vol*(1-ALPHA-BETA);\n  m.sig=Math.sqrt(omega+ALPHA*eps*eps+BETA*m.sig*m.sig);\n  if(R()<.004) m.sig*=2.2; // rare shock seeds a volatile cluster\n  m.prev=m.price;\n  var np=m.price*Math.exp(eps);\n  np=Math.round(np/m.step)*m.step;\n  if(np<=0) np=m.step;\n  m.price=np;\n  if(np>m.high24) m.high24=np;\n  if(np<m.low24) m.low24=np;\n  var now=Date.now();\n  if(now-m.sparkT>24000){m.spark.push(np);if(m.spark.length>60) m.spark.shift();m.sparkT=now;}\n  else m.spark[m.spark.length-1]=np;\n  return np-m.prev;\n}\n\n/* ——— candle history ——— */\nvar tf=15;\nvar candles=[];\nvar MA_N=[7,25,99],MA_ON=[true,true,true],MA_COL=['#f0b90b','#58a6ff','#c678dd'];\nvar ma=[[],[],[]];\nfunction genHistory(){\n  var m=INST[sel];\n  var r=mulberry(sel*131+tf*7+3);\n  var N=420, ms=tf*60000;\n  var base=.03*Math.sqrt(tf/1440);          // ≈3% daily volatility, scaled to the candle\n  var sig=base, omega=base*base*(1-ALPHA-BETA);\n  var closes=[],opens=[],highs=[],lows=[],vols=[];\n  var p=100, drift=gauss(r)*base*.05;\n  for(var i=0;i<N;i++){\n    var z=gauss(r),e=sig*z;\n    sig=Math.sqrt(omega+ALPHA*e*e+BETA*sig*sig);\n    if(r()<.01) sig*=2;\n    var o=p,c=p*Math.exp(e+drift);\n    var h=Math.max(o,c)*(1+Math.abs(gauss(r))*sig*.55);\n    var l=Math.min(o,c)*(1-Math.abs(gauss(r))*sig*.55);\n    opens.push(o);closes.push(c);highs.push(h);lows.push(l);\n    vols.push((.6+Math.abs(e)/base*.9+r()*.5)*(800+r()*400)*Math.sqrt(tf));\n    p=c;\n  }\n  var k=m.price/p;\n  // bend the path so the candle 24h ago opens at the instrument's 24h open\n  var j24=N-Math.round(1440/tf);\n  var bend=[];for(var b=0;b<N;b++) bend.push(0);\n  if(j24>=0&&j24<N-1){\n    var delta=Math.log(m.open24/(opens[j24]*k));\n    for(var b2=0;b2<N;b2++) bend[b2]=b2<=j24?delta:delta*(N-1-b2)/(N-1-j24);\n  }\n  var now=Date.now(),t0=Math.floor(now/ms)*ms;\n  candles=[];\n  for(var j=0;j<N;j++){\n    var f=k*Math.exp(bend[j]);\n    candles.push({t:t0-(N-1-j)*ms,o:opens[j]*f,h:highs[j]*f,l:lows[j]*f,c:closes[j]*f,v:vols[j]});\n  }\n  var last=candles[N-1];last.c=m.price;last.h=Math.max(last.h,m.price);last.l=Math.min(last.l,m.price);\n  computeMA();\n}\nfunction computeMA(){\n  for(var q=0;q<3;q++){\n    var n=MA_N[q],arr=ma[q];arr.length=candles.length;var s=0;\n    for(var i=0;i<candles.length;i++){\n      s+=candles[i].c;\n      if(i>=n) s-=candles[i-n].c;\n      arr[i]=i>=n-1?s/n:NaN;\n    }\n  }\n}\nfunction liveCandle(price,size){\n  var ms=tf*60000,now=Date.now();\n  var last=candles[candles.length-1];\n  if(now>=last.t+ms){\n    var nt=Math.floor(now/ms)*ms;\n    candles.push({t:nt,o:last.c,h:Math.max(last.c,price),l:Math.min(last.c,price),c:price,v:size});\n    if(candles.length>900) candles.shift(); else view.end+=1,view.tEnd+=1;\n  }else{\n    last.c=price;if(price>last.h) last.h=price;if(price<last.l) last.l=price;last.v+=size;\n  }\n  computeMA();\n  chartDirty=true;\n}\n\n/* ——— chart ——— */\nvar cv=$('chart'),cx=cv.getContext('2d'),box=$('chartBox');\nvar CW=0,CH=0,DPR=1;\nvar AX=66,TH=22;\nvar view={barW:9,tBarW:9,end:0,tEnd:0,yMin:0,yMax:1,vMax:1,init:false};\nvar hover={on:false,x:0,y:0};\nvar chartDirty=true;\nfunction sizeChart(){\n  var w=box.clientWidth,h=box.clientHeight;\n  if(!w||!h) return;\n  DPR=Math.min(2,window.devicePixelRatio||1);\n  var big=CW&&Math.abs(w-CW)/CW>.25;\n  CW=w;CH=h;\n  if(view.init&&big) resetView();\n  cv.width=Math.round(w*DPR);cv.height=Math.round(h*DPR);\n  cv.style.width=w+'px';cv.style.height=h+'px';\n  chartDirty=true;\n}\nfunction resetView(){\n  var pw=Math.max(100,CW-AX);\n  view.tBarW=clamp(pw/90,5,14);\n  view.tEnd=candles.length-1+6;\n  if(!view.init){view.barW=view.tBarW;view.end=view.tEnd;view.init=true;}\n  chartDirty=true;\n}\nfunction niceStep(range,target){\n  var raw=range/target,mag=Math.pow(10,Math.floor(Math.log10(raw))),n=raw/mag;\n  var s=n<1.5?1:n<3?2:n<7?5:10;return s*mag;\n}\nfunction fmtT(t,full){\n  var d=new Date(t);\n  var hh=('0'+d.getUTCHours()).slice(-2),mm=('0'+d.getUTCMinutes()).slice(-2);\n  var mon=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][d.getUTCMonth()];\n  if(tf>=1440) return d.getUTCDate()+' '+mon+(full?' '+d.getUTCFullYear():'');\n  if(tf>=60) return full?d.getUTCDate()+' '+mon+' '+hh+':'+mm:(d.getUTCHours()===0?d.getUTCDate()+' '+mon:hh+':'+mm);\n  return full?d.getUTCDate()+' '+mon+' '+hh+':'+mm:hh+':'+mm;\n}\nfunction drawChart(){\n  if(!CW||!candles.length) return;\n  var m=INST[sel];\n  var ctx=cx;\n  ctx.setTransform(DPR,0,0,DPR,0,0);\n  ctx.clearRect(0,0,CW,CH);\n  var PW=CW-AX,PH=CH-TH;\n  var volH=PH*.17,priceH=PH-volH-8,pad=14,padT=CW<560?50:34;\n  var bw=view.barW,end=view.end;\n  var i0=Math.max(0,Math.floor(end-PW/bw)-1),i1=Math.min(candles.length-1,Math.ceil(end));\n  // y range targets\n  var lo=Infinity,hi=-Infinity,vm=0;\n  for(var i=i0;i<=i1;i++){\n    var c=candles[i];if(c.l<lo) lo=c.l;if(c.h>hi) hi=c.h;if(c.v>vm) vm=c.v;\n  }\n  if(!isFinite(lo)){lo=m.price*.99;hi=m.price*1.01;vm=1;}\n  var span=(hi-lo)||hi*.01;\n  var tMin=lo-span*.07,tMax=hi+span*.07;\n  var k=view.snap?1:.2;\n  view.yMin+=(tMin-view.yMin)*k;view.yMax+=(tMax-view.yMax)*k;view.vMax+=(vm-view.vMax)*k;\n  view.snap=false;\n  if(Math.abs(tMin-view.yMin)>span*.001||Math.abs(tMax-view.yMax)>span*.001) chartDirty=true;\n  var yMin=view.yMin,yMax=view.yMax;\n  function Y(p){return padT+(yMax-p)/(yMax-yMin)*(priceH-pad-padT);}\n  function X(i){return PW-(end-i-.5)*bw;}\n\n  // background glow + watermark\n  var g=ctx.createRadialGradient(PW*.3,PH*.2,10,PW*.3,PH*.2,PW*.8);\n  g.addColorStop(0,'rgba(240,185,11,.045)');g.addColorStop(1,'rgba(240,185,11,0)');\n  ctx.fillStyle=g;ctx.fillRect(0,0,PW,PH);\n  ctx.save();\n  ctx.font='700 '+Math.round(clamp(PW*.09,28,84))+'px '+sansFam;\n  ctx.fillStyle='rgba(255,255,255,.028)';ctx.textAlign='center';ctx.textBaseline='middle';\n  ctx.fillText(m.sym+' · '+tfLabel(),PW/2,priceH*.52);\n  ctx.restore();\n\n  // grid + price axis\n  var st=niceStep(yMax-yMin,Math.max(3,Math.floor(priceH/60)));\n  ctx.lineWidth=1;ctx.font='11px '+monoFam;ctx.textBaseline='middle';ctx.textAlign='left';\n  for(var pv=Math.ceil(yMin/st)*st;pv<=yMax;pv+=st){\n    var yy=Math.round(Y(pv))+.5;\n    if(yy<4||yy>priceH-2) continue;\n    ctx.strokeStyle='rgba(255,255,255,.045)';ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(PW,yy);ctx.stroke();\n    ctx.fillStyle='#626c78';ctx.fillText(fmt(pv,m.dp),PW+8,yy);\n  }\n  // time grid\n  var every=Math.max(1,Math.ceil(96/bw));\n  var nice=[1,2,3,4,6,8,12,16,24,32,48,64,96,128];\n  for(var q=0;q<nice.length;q++){if(nice[q]>=every){every=nice[q];break;}}\n  ctx.textAlign='center';ctx.textBaseline='middle';\n  for(var ti=i0-(i0%every);ti<=i1;ti+=every){\n    if(ti<0) continue;\n    var tx=Math.round(X(ti))+.5;\n    if(tx<0||tx>PW) continue;\n    ctx.strokeStyle='rgba(255,255,255,.035)';ctx.beginPath();ctx.moveTo(tx,0);ctx.lineTo(tx,PH);ctx.stroke();\n    ctx.fillStyle='#626c78';ctx.fillText(fmtT(candles[ti].t,false),tx,PH+TH/2+1);\n  }\n  // axes separators\n  ctx.strokeStyle='rgba(255,255,255,.08)';\n  ctx.beginPath();ctx.moveTo(PW+.5,0);ctx.lineTo(PW+.5,CH);ctx.moveTo(0,PH+.5);ctx.lineTo(CW,PH+.5);ctx.stroke();\n  ctx.strokeStyle='rgba(255,255,255,.05)';ctx.beginPath();ctx.moveTo(0,priceH+4.5);ctx.lineTo(PW,priceH+4.5);ctx.stroke();\n\n  // clip to plot\n  ctx.save();ctx.beginPath();ctx.rect(0,0,PW,PH);ctx.clip();\n  // volume\n  var vTop=priceH+8,vMaxv=view.vMax||1;\n  var body=Math.max(1,Math.floor(bw*.68));\n  for(var vi=i0;vi<=i1;vi++){\n    var cc=candles[vi],up=cc.c>=cc.o;\n    var vx=Math.round(X(vi)-body/2);\n    var vh=Math.max(1,(cc.v/vMaxv)*(volH-6));\n    ctx.fillStyle=up?'rgba(22,199,132,.32)':'rgba(234,57,67,.32)';\n    ctx.fillRect(vx,PH-vh,body,vh);\n  }\n  // candles\n  for(var ci=i0;ci<=i1;ci++){\n    var cd=candles[ci],isUp=cd.c>=cd.o;\n    var cxp=Math.round(X(ci));\n    var col=isUp?'#16c784':'#ea3943';\n    ctx.fillStyle=col;\n    var yh=Y(cd.h),yl=Y(cd.l);\n    ctx.fillRect(cxp,Math.round(yh),1,Math.max(1,Math.round(yl-yh)));\n    var yo=Y(cd.o),yc=Y(cd.c);\n    var top=Math.round(Math.min(yo,yc)),bh=Math.max(1,Math.round(Math.abs(yc-yo)));\n    ctx.fillRect(cxp-Math.floor(body/2),top,body,bh);\n  }\n  // moving averages\n  ctx.lineWidth=1.3;ctx.lineJoin='round';\n  for(var mi=0;mi<3;mi++){\n    if(!MA_ON[mi]) continue;\n    ctx.strokeStyle=MA_COL[mi];ctx.globalAlpha=.9;ctx.beginPath();var started=false;\n    for(var ai=i0;ai<=i1;ai++){\n      var mv=ma[mi][ai];if(!(mv>0)) continue;\n      var ax=X(ai),ay=Y(mv);\n      if(!started){ctx.moveTo(ax,ay);started=true;}else ctx.lineTo(ax,ay);\n    }\n    ctx.stroke();ctx.globalAlpha=1;\n  }\n  // last price line\n  var lastC=candles[candles.length-1];\n  var lup=m.price>=lastC.o;\n  var ly=Math.round(Y(m.price))+.5;\n  ctx.setLineDash([2,3]);ctx.strokeStyle=lup?'rgba(22,199,132,.8)':'rgba(234,57,67,.8)';\n  ctx.beginPath();ctx.moveTo(0,ly);ctx.lineTo(PW,ly);ctx.stroke();ctx.setLineDash([]);\n  var lx=X(candles.length-1);\n  if(lx>0&&lx<PW){\n    var pulse=(performance.now()%1600)/1600;\n    ctx.fillStyle=lup?'rgba(22,199,132,'+(0.35*(1-pulse))+')':'rgba(234,57,67,'+(0.35*(1-pulse))+')';\n    ctx.beginPath();ctx.arc(lx,Y(m.price),3+pulse*9,0,Math.PI*2);ctx.fill();\n    chartDirty=true;\n  }\n  ctx.restore();\n\n  // last price tag\n  ctx.fillStyle=lup?'#16c784':'#ea3943';\n  roundRect(ctx,PW+1,ly-10,AX-3,20,3);ctx.fill();\n  ctx.fillStyle='#fff';ctx.font='600 11px '+monoFam;ctx.textAlign='left';ctx.textBaseline='middle';\n  ctx.fillText(fmt(m.price,m.dp),PW+7,ly+.5);\n\n  // crosshair\n  var hi2=-1;\n  if(hover.on&&hover.x<PW&&hover.y<PH){\n    hi2=Math.round(end-.5-(PW-hover.x)/bw);\n    if(hi2<0||hi2>=candles.length) hi2=-1;\n    var hx=hi2>=0?Math.round(X(hi2))+.5:hover.x;\n    ctx.setLineDash([4,4]);ctx.strokeStyle='rgba(231,233,236,.35)';ctx.lineWidth=1;\n    ctx.beginPath();ctx.moveTo(hx,0);ctx.lineTo(hx,PH);ctx.moveTo(0,Math.round(hover.y)+.5);ctx.lineTo(PW,Math.round(hover.y)+.5);ctx.stroke();ctx.setLineDash([]);\n    if(hover.y<priceH){\n      var hp=yMax-(hover.y-padT)/(priceH-pad-padT)*(yMax-yMin);\n      ctx.fillStyle='#2a313b';roundRect(ctx,PW+1,hover.y-10,AX-3,20,3);ctx.fill();\n      ctx.fillStyle='#e7e9ec';ctx.font='11px '+monoFam;ctx.fillText(fmt(hp,m.dp),PW+7,hover.y+.5);\n    }\n    if(hi2>=0){\n      var lbl=fmtT(candles[hi2].t,true);ctx.font='11px '+monoFam;\n      var tw=ctx.measureText(lbl).width+14;\n      ctx.fillStyle='#2a313b';roundRect(ctx,clamp(hx-tw/2,0,PW-tw),PH+2,tw,TH-4,3);ctx.fill();\n      ctx.fillStyle='#e7e9ec';ctx.textAlign='center';ctx.fillText(lbl,clamp(hx,tw/2,PW-tw/2),PH+TH/2+1);\n    }\n  }\n  updateLegend(hi2>=0?hi2:candles.length-1,hi2>=0);\n}\nfunction roundRect(c,x,y,w,h,r){c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+h,r);c.arcTo(x+w,y+h,x,y+h,r);c.arcTo(x,y+h,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath();}\nvar monoFam=getComputedStyle(document.documentElement).getPropertyValue('--mono')||'monospace';\nvar sansFam=getComputedStyle(document.body).fontFamily||'sans-serif';\nfunction tfLabel(){return {1:'1m',5:'5m',15:'15m',60:'1H',240:'4H',1440:'1D'}[tf];}\nvar ohlcEl=$('ohlc'),ctip=$('ctip'),lastLegend='';\nfunction updateLegend(i,fromHover){\n  var c=candles[i],m=INST[sel];if(!c) return;\n  var ch=(c.c-c.o)/c.o,cls=ch>=0?'up':'down';\n  var s='<span>O <b class=\"'+cls+'\">'+fmt(c.o,m.dp)+'</b></span><span>H <b class=\"'+cls+'\">'+fmt(c.h,m.dp)+'</b></span><span>L <b class=\"'+cls+'\">'+fmt(c.l,m.dp)+'</b></span><span>C <b class=\"'+cls+'\">'+fmt(c.c,m.dp)+'</b></span><span class=\"'+cls+'\">'+pct(ch)+'</span>';\n  if(s!==lastLegend){ohlcEl.innerHTML=s;lastLegend=s;}\n  for(var q=0;q<3;q++){var v=ma[q][i];$('ma'+q).textContent=v>0?fmt(v,m.dp):'—';}\n  if(fromHover){\n    ctip.innerHTML='<div class=\"t\">'+fmtT(c.t,true)+' UTC</div>'+\n      '<div class=\"r\"><span>Open</span><span>'+fmt(c.o,m.dp)+'</span></div>'+\n      '<div class=\"r\"><span>High</span><span>'+fmt(c.h,m.dp)+'</span></div>'+\n      '<div class=\"r\"><span>Low</span><span>'+fmt(c.l,m.dp)+'</span></div>'+\n      '<div class=\"r\"><span>Close</span><span class=\"'+cls+'\">'+fmt(c.c,m.dp)+'</span></div>'+\n      '<div class=\"r\"><span>Change</span><span class=\"'+cls+'\">'+pct(ch)+'</span></div>'+\n      '<div class=\"r\"><span>Volume</span><span>'+compact(c.v)+'</span></div>';\n    var tw=ctip.offsetWidth,th=ctip.offsetHeight;\n    var x=hover.x+16,y=hover.y+16;\n    if(x+tw>CW-AX) x=hover.x-tw-16;\n    if(y+th>CH-TH) y=hover.y-th-16;\n    ctip.style.transform='translate('+Math.round(Math.max(4,x))+'px,'+Math.round(Math.max(4,y))+'px)';\n    ctip.classList.add('show');\n  }else ctip.classList.remove('show');\n}\n\n/* chart interaction */\nvar drag=null,pointers={},pinch=null,vel=0;\nbox.addEventListener('pointerdown',function(e){\n  box.setPointerCapture&&box.setPointerCapture(e.pointerId);\n  pointers[e.pointerId]={x:e.clientX,y:e.clientY};\n  var ids=Object.keys(pointers);\n  if(ids.length===2){\n    var a=pointers[ids[0]],b=pointers[ids[1]];\n    pinch={d:Math.hypot(a.x-b.x,a.y-b.y),bw:view.tBarW};drag=null;\n  }else{\n    drag={x:e.clientX,end:view.tEnd,t:performance.now(),lx:e.clientX};vel=0;\n  }\n  setHover(e);\n});\nbox.addEventListener('pointermove',function(e){\n  if(pointers[e.pointerId]){pointers[e.pointerId].x=e.clientX;pointers[e.pointerId].y=e.clientY;}\n  if(pinch){\n    var ids=Object.keys(pointers);if(ids.length<2) return;\n    var a=pointers[ids[0]],b=pointers[ids[1]];\n    var d=Math.hypot(a.x-b.x,a.y-b.y);\n    view.tBarW=clamp(pinch.bw*d/pinch.d,2.5,42);chartDirty=true;return;\n  }\n  if(drag){\n    var dx=e.clientX-drag.x;\n    view.tEnd=clampEnd(drag.end-dx/view.barW);view.end=view.tEnd;\n    var now=performance.now(),dt=Math.max(1,now-drag.t);\n    vel=(e.clientX-drag.lx)/dt;drag.t=now;drag.lx=e.clientX;\n    chartDirty=true;\n  }\n  setHover(e);\n});\nfunction endPtr(e){\n  delete pointers[e.pointerId];\n  if(pinch&&Object.keys(pointers).length<2) pinch=null;\n  if(drag){\n    if(Math.abs(vel)>.05&&!reduce) view.tEnd=clampEnd(view.tEnd-vel*260/view.barW);\n    drag=null;\n  }\n  if(e.pointerType!=='mouse'){hover.on=false;chartDirty=true;}\n}\nbox.addEventListener('pointerup',endPtr);\nbox.addEventListener('pointercancel',endPtr);\nbox.addEventListener('pointerleave',function(e){if(e.pointerType==='mouse'){hover.on=false;chartDirty=true;}});\nfunction setHover(e){\n  var r=box.getBoundingClientRect();\n  hover.x=e.clientX-r.left;hover.y=e.clientY-r.top;hover.on=true;chartDirty=true;\n}\nfunction clampEnd(v){\n  var vis=(CW-AX)/view.tBarW;\n  return clamp(v,Math.min(candles.length-1,vis*.35),candles.length-1+vis*.3);\n}\nbox.addEventListener('wheel',function(e){\n  e.preventDefault();\n  var r=box.getBoundingClientRect(),mx=e.clientX-r.left;\n  zoomAt(Math.exp(-e.deltaY*.0016),mx);\n},{passive:false});\nfunction zoomAt(f,mx){\n  var PW=CW-AX;\n  var nb=clamp(view.tBarW*f,2.5,42);\n  var idxAt=view.tEnd-(PW-mx)/view.tBarW;\n  view.tBarW=nb;\n  view.tEnd=clampEnd(idxAt+(PW-mx)/nb);\n  chartDirty=true;\n}\nbox.addEventListener('dblclick',function(){resetView();});\nbox.addEventListener('keydown',function(e){\n  var PW=CW-AX;\n  if(e.key==='ArrowLeft'){view.tEnd=clampEnd(view.tEnd-8);chartDirty=true;e.preventDefault();}\n  else if(e.key==='ArrowRight'){view.tEnd=clampEnd(view.tEnd+8);chartDirty=true;e.preventDefault();}\n  else if(e.key==='+'||e.key==='='){zoomAt(1.25,PW);e.preventDefault();}\n  else if(e.key==='-'||e.key==='_'){zoomAt(.8,PW);e.preventDefault();}\n  else if(e.key==='0'||e.key==='Home'){resetView();e.preventDefault();}\n});\n$('zIn').addEventListener('click',function(){zoomAt(1.3,CW-AX);});\n$('zOut').addEventListener('click',function(){zoomAt(1/1.3,CW-AX);});\n$('zReset').addEventListener('click',resetView);\nArray.prototype.forEach.call(document.querySelectorAll('[data-tf]'),function(b){\n  b.addEventListener('click',function(){\n    tf=+b.getAttribute('data-tf');\n    Array.prototype.forEach.call(document.querySelectorAll('[data-tf]'),function(o){o.setAttribute('aria-pressed',String(o===b));});\n    genHistory();view.init=false;resetView();view.snap=true;\n  });\n});\nArray.prototype.forEach.call(document.querySelectorAll('[data-ma]'),function(b){\n  b.addEventListener('click',function(){\n    var i=+b.getAttribute('data-ma');MA_ON[i]=!MA_ON[i];b.setAttribute('aria-pressed',String(MA_ON[i]));chartDirty=true;\n  });\n});\n\n/* ——— order book ——— */\nvar ROWS=11,bookView='both';\nvar sizes=new Map(),askRows=[],bidRows=[],lastBook={a:[],b:[]};\nvar asksEl=$('asks'),bidsEl=$('bids');\nfunction mkRow(){\n  var d=document.createElement('div');d.className='brow';\n  d.innerHTML='<i class=\"bar\"></i><span></span><span></span><span></span>';\n  d.addEventListener('click',function(){var p=d.getAttribute('data-p');if(p){setPrice(+p);}});\n  return d;\n}\nfunction layoutBook(){\n  var body=$('bookBody').clientHeight;\n  var n=body?Math.floor((body-44)/2/19):11;\n  if(bookView!=='both') n=n*2+1;\n  ROWS=clamp(n,5,40);\n  asksEl.innerHTML='';bidsEl.innerHTML='';askRows=[];bidRows=[];\n  var na=bookView==='bids'?0:ROWS,nb=bookView==='asks'?0:ROWS;\n  for(var i=0;i<na;i++){var a=mkRow();askRows.push(a);asksEl.insertBefore(a,asksEl.firstChild);}\n  for(var j=0;j<nb;j++){var b=mkRow();bidRows.push(b);bidsEl.appendChild(b);}\n  asksEl.style.display=na?'':'none';bidsEl.style.display=nb?'':'none';\n  renderBook(true);\n}\nfunction sizeFor(key,k){\n  var s=sizes.get(key);\n  if(s===undefined){\n    var m=INST[sel];\n    s=(Math.exp(gauss(R)*.8)*(1+k*.18))*(2600/m.p)*(R()<.05?6:1);\n    sizes.set(key,s);\n  }\n  return s;\n}\nfunction renderBook(full){\n  var m=INST[sel];\n  var st=m.step*(m.p>1000?1:m.p>100?2:m.p>10?3:5);\n  var bestAsk=Math.ceil((m.price+st*.5)/st)*st,bestBid=bestAsk-st;\n  var dpA=m.dp;\n  var ca=0,cb=0,asks=[],bids=[];\n  for(var i=0;i<ROWS;i++){\n    var pa=bestAsk+i*st,pb=bestBid-i*st;\n    var ka=pa.toFixed(dpA),kb=pb.toFixed(dpA);\n    var sa=sizeFor(ka,i),sb=sizeFor(kb,i);\n    ca+=sa;cb+=sb;asks.push([pa,sa,ca,ka]);bids.push([pb,sb,cb,kb]);\n  }\n  var maxC=Math.max(ca,cb);\n  function paint(rows,data,old){\n    for(var r=0;r<rows.length;r++){\n      var row=rows[r],d=data[r];\n      var sp=row.children;\n      var ps=fmt(d[0],m.dp),ss=fmt(d[1],d[1]<10?3:2),cs=compact(d[2]*d[0]);\n      if(sp[1].textContent!==ps) sp[1].textContent=ps;\n      if(sp[2].textContent!==ss){\n        sp[2].textContent=ss;\n        if(!full&&old[r]&&old[r]===d[3]){row.className='brow '+(row.className.indexOf('fa')>0?'fb':'fa');}\n      }\n      if(sp[3].textContent!==cs) sp[3].textContent=cs;\n      row.setAttribute('data-p',d[0]);\n      row.children[0].style.width=(d[2]/maxC*100).toFixed(1)+'%';\n    }\n  }\n  paint(askRows,asks,lastBook.a);paint(bidRows,bids,lastBook.b);\n  lastBook.a=asks.map(function(x){return x[3];});lastBook.b=bids.map(function(x){return x[3];});\n  $('spVal').textContent=fmt(bestAsk-bestBid,m.dp)+' ('+((bestAsk-bestBid)/m.price*100).toFixed(3)+'%)';\n  if(sizes.size>600){var keep=new Set(lastBook.a.concat(lastBook.b));sizes.forEach(function(v,k){if(!keep.has(k)) sizes.delete(k);});}\n}\nfunction jiggleBook(){\n  var m=INST[sel];\n  sizes.forEach(function(v,k){\n    if(R()<.22) sizes.set(k,Math.max(.001,v*Math.exp(gauss(R)*.35)));\n  });\n}\nArray.prototype.forEach.call(document.querySelectorAll('[data-bv]'),function(b){\n  b.addEventListener('click',function(){\n    bookView=b.getAttribute('data-bv');\n    Array.prototype.forEach.call(document.querySelectorAll('[data-bv]'),function(o){o.setAttribute('aria-pressed',String(o===b));});\n    layoutBook();\n  });\n});\n\n/* ——— trades feed ——— */\nvar tlist=$('tlist'),TMAX=40;\nfunction addTrade(price,size,side,mine){\n  var m=INST[sel];\n  var d=document.createElement('div');\n  d.className='trow'+(reduce?'':' new')+(mine?' mine':'');\n  var t=new Date(),ts=('0'+t.getUTCHours()).slice(-2)+':'+('0'+t.getUTCMinutes()).slice(-2)+':'+('0'+t.getUTCSeconds()).slice(-2);\n  d.innerHTML='<span class=\"'+(side>0?'up':'down')+'\">'+fmt(price,m.dp)+'</span><span style=\"text-align:right\">'+fmt(size,size<10?3:2)+'</span><span style=\"text-align:right\"'+(mine?' title=\"Your order (simulated)\"':'')+'>'+(mine?'◆ ':'')+ts+'</span>';\n  tlist.insertBefore(d,tlist.firstChild);\n  while(tlist.children.length>TMAX) tlist.removeChild(tlist.lastChild);\n}\nfunction seedTrades(){\n  tlist.innerHTML='';\n  var m=INST[sel];\n  for(var i=0;i<TMAX;i++){\n    var p=m.price*(1+gauss(R)*m.vol*3);p=Math.round(p/m.step)*m.step;\n    var d=document.createElement('div');d.className='trow';\n    var t=new Date(Date.now()-i*1300-R()*900);\n    var ts=('0'+t.getUTCHours()).slice(-2)+':'+('0'+t.getUTCMinutes()).slice(-2)+':'+('0'+t.getUTCSeconds()).slice(-2);\n    var sz=Math.exp(gauss(R))*(900/m.p);\n    d.innerHTML='<span class=\"'+(R()<.5?'up':'down')+'\">'+fmt(p,m.dp)+'</span><span style=\"text-align:right\">'+fmt(sz,sz<10?3:2)+'</span><span style=\"text-align:right\">'+ts+'</span>';\n    tlist.appendChild(d);\n  }\n}\n\n/* ——— watchlist + tape ——— */\nvar wl=$('wl'),tape=$('tape');\nfunction sparkPath(arr,w,h){\n  var mn=Infinity,mx=-Infinity;for(var i=0;i<arr.length;i++){if(arr[i]<mn)mn=arr[i];if(arr[i]>mx)mx=arr[i];}\n  var sp=(mx-mn)||1,d='';\n  for(var j=0;j<arr.length;j++){\n    var x=j/(arr.length-1)*w,y=h-2-(arr[j]-mn)/sp*(h-4);\n    d+=(j?'L':'M')+x.toFixed(1)+' '+y.toFixed(1);\n  }\n  return d;\n}\nfunction buildWatch(){\n  var html='';\n  INST.forEach(function(m,i){\n    html+='<li><button type=\"button\" class=\"wrow'+(i===sel?' sel':'')+'\" data-i=\"'+i+'\" aria-label=\"'+m.name+' ('+m.sym+')\">'+\n      '<span class=\"s\"><b>'+m.sym+'</b><small>'+m.name+'</small></span>'+\n      '<svg viewBox=\"0 0 64 26\" aria-hidden=\"true\"><defs><linearGradient id=\"sg'+i+'\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"currentColor\" stop-opacity=\".28\"/><stop offset=\"1\" stop-color=\"currentColor\" stop-opacity=\"0\"/></linearGradient></defs><path class=\"sa\" fill=\"url(#sg'+i+')\"/><path class=\"sl\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" stroke-linejoin=\"round\"/></svg>'+\n      '<span class=\"q\"><span class=\"px\" data-px=\"'+i+'\"></span><span class=\"pct\" data-pc=\"'+i+'\"></span></span></button></li>';\n  });\n  wl.innerHTML=html;\n  var th='';\n  for(var c=0;c<2;c++){\n    INST.forEach(function(m,i){\n      th+='<span class=\"tk\"'+(c?' aria-hidden=\"true\"':'')+'><b>'+m.sym+'</b><span class=\"px\" data-tpx=\"'+i+'\"></span><span class=\"ch\" data-tch=\"'+i+'\"></span></span>';\n    });\n  }\n  tape.innerHTML=th;\n  INST.forEach(function(m,i){paintInst(i,0);});\n}\nvar flip={};\nfunction flash(el,dir,key){\n  flip[key]=!flip[key];\n  el.classList.remove('fu','fu2','fd','fd2');\n  if(reduce) return;\n  el.classList.add(dir>0?(flip[key]?'fu':'fu2'):(flip[key]?'fd':'fd2'));\n}\nfunction paintInst(i,dir){\n  var m=INST[i],ch=m.price/m.open24-1,cls=ch>=0?'up':'down';\n  var btn=wl.querySelector('[data-i=\"'+i+'\"]');\n  if(btn){\n    var px=btn.querySelector('[data-px]');px.textContent=fmt(m.price,m.dp);\n    var pc=btn.querySelector('[data-pc]');pc.textContent=pct(ch);pc.className='pct '+cls;\n    var svg=btn.querySelector('svg');svg.style.color=ch>=0?'#16c784':'#ea3943';\n    var d=sparkPath(m.spark,64,26);\n    svg.querySelector('.sl').setAttribute('d',d);\n    svg.querySelector('.sa').setAttribute('d',d+'L64 26L0 26Z');\n    if(dir) flash(px,dir,'w'+i);\n  }\n  Array.prototype.forEach.call(tape.querySelectorAll('[data-tpx=\"'+i+'\"]'),function(el,k){\n    el.textContent=fmt(m.price,m.dp);if(dir&&k===0) flash(el,dir,'t'+i);\n  });\n  Array.prototype.forEach.call(tape.querySelectorAll('[data-tch=\"'+i+'\"]'),function(el){el.textContent=pct(ch);el.className='ch '+cls;});\n}\nwl.addEventListener('click',function(e){\n  var b=e.target.closest('.wrow');if(!b) return;\n  selectInst(+b.getAttribute('data-i'));\n  if(isMobile()) showPanel('p-chart');\n});\n$('wlSearch').addEventListener('input',function(){\n  var q=this.value.trim().toLowerCase();\n  Array.prototype.forEach.call(wl.querySelectorAll('.wrow'),function(b){\n    var m=INST[+b.getAttribute('data-i')];\n    b.parentNode.style.display=(!q||m.sym.toLowerCase().indexOf(q)>=0||m.name.toLowerCase().indexOf(q)>=0)?'':'none';\n  });\n});\n\n/* ——— header & instrument panel ——— */\nvar bigPx=$('bigPx');\nfunction paintHead(dir){\n  var m=INST[sel],ch=m.price/m.open24-1;\n  bigPx.textContent=fmt(m.price,m.dp);\n  bigPx.className='bigpx '+(m.price>=m.prev?'up':'down');\n  if(dir) flash(bigPx,dir,'big');\n  var s=$('s24c');s.textContent=pct(ch);s.className=ch>=0?'up':'down';\n  $('s24h').textContent=fmt(m.high24,m.dp);$('s24l').textContent=fmt(m.low24,m.dp);\n  $('s24v').textContent=compact(m.vol24)+' '+m.sym;\n  var sl=$('spLast');sl.className='last '+(m.price>=m.prev?'up':'down');\n  $('spLastTxt').textContent=fmt(m.price,m.dp);\n  document.title=fmt(m.price,m.dp)+' '+m.sym+' · QUANTA (simulated)';\n}\nfunction selectInst(i){\n  sel=i;var m=INST[i];\n  Array.prototype.forEach.call(wl.querySelectorAll('.wrow'),function(b){b.classList.toggle('sel',+b.getAttribute('data-i')===i);});\n  $('pairName').innerHTML=m.sym+' <span>/ QD</span>';\n  $('pairLong').textContent=m.name;\n  var coin=$('coin');coin.textContent=m.sym.slice(0,2);coin.style.background='radial-gradient(circle at 30% 30%,#fff8,transparent 60%),'+m.col;\n  Array.prototype.forEach.call(document.querySelectorAll('.sym'),function(s){s.textContent=m.sym;});\n  $('bookAmtH').textContent='Amount ('+m.sym+')';$('trAmtH').textContent='Amount ('+m.sym+')';\n  sizes.clear();lastBook={a:[],b:[]};\n  genHistory();view.init=false;resetView();view.snap=true;\n  renderBook(true);seedTrades();paintHead(0);\n  resetForms();\n}\n\n/* ——— portfolio ——— */\nvar donut=$('donut'),legend=$('legend');\nvar NS='http://www.w3.org/2000/svg';\nvar arcs=[],legendRows=[],hoverSeg=-1;\nfunction holdings(){\n  var list=[];\n  INST.forEach(function(m){if(m.hold>1e-9) list.push({k:m.sym,n:m.name,v:m.hold*m.price,c:m.col});});\n  list.push({k:'QD',n:'Cash (Quanta Dollars)',v:cash,c:'#5b6675'});\n  return list;\n}\nvar startEquity=0;\nfunction buildDonut(){\n  donut.innerHTML='';\n  var bg=document.createElementNS(NS,'circle');\n  bg.setAttribute('cx',80);bg.setAttribute('cy',80);bg.setAttribute('r',62);bg.setAttribute('fill','none');bg.setAttribute('stroke','#1d232d');bg.setAttribute('stroke-width','16');\n  donut.appendChild(bg);\n  arcs=[];\n  var tx=document.createElementNS(NS,'text');tx.setAttribute('x',80);tx.setAttribute('y',76);tx.setAttribute('text-anchor','middle');tx.setAttribute('font-size','9.5');tx.setAttribute('fill','#626c78');tx.style.fontFamily='inherit';tx.textContent='TOTAL EQUITY';donut.appendChild(tx);\n  var tv=document.createElementNS(NS,'text');tv.setAttribute('x',80);tv.setAttribute('y',93);tv.setAttribute('text-anchor','middle');tv.setAttribute('font-size','14');tv.setAttribute('font-weight','600');tv.id='dTot';donut.appendChild(tv);\n  paintDonut(true);\n}\nfunction paintDonut(rebuild){\n  var h=holdings(),tot=h.reduce(function(s,x){return s+x.v;},0);\n  var C=2*Math.PI*62,off=0,gap=1.6;\n  if(rebuild||arcs.length!==h.length){\n    arcs.forEach(function(a){a.remove();});arcs=[];\n    h.forEach(function(x,i){\n      var c=document.createElementNS(NS,'circle');\n      c.setAttribute('cx',80);c.setAttribute('cy',80);c.setAttribute('r',62);c.setAttribute('fill','none');\n      c.setAttribute('stroke-width','16');c.setAttribute('class','seg-arc');c.setAttribute('transform','rotate(-90 80 80)');\n      c.addEventListener('pointerenter',function(){hoverSeg=i;hl();});\n      c.addEventListener('pointerleave',function(){hoverSeg=-1;hl();});\n      donut.insertBefore(c,donut.children[1]);arcs.push(c);\n    });\n    legend.innerHTML=h.map(function(x,i){return '<li data-l=\"'+i+'\" title=\"'+x.n+'\"><i style=\"background:'+x.c+'\"></i><span class=\"n\">'+x.k+'</span><span class=\"v\"></span></li>';}).join('');\n    legendRows=Array.prototype.slice.call(legend.children);\n    legendRows.forEach(function(li,i){\n      li.addEventListener('pointerenter',function(){hoverSeg=i;hl();});\n      li.addEventListener('pointerleave',function(){hoverSeg=-1;hl();});\n    });\n  }\n  h.forEach(function(x,i){\n    var len=Math.max(0,x.v/tot*C-gap);\n    var a=arcs[i];\n    a.setAttribute('stroke',x.c);\n    a.setAttribute('stroke-dasharray',len.toFixed(2)+' '+(C-len).toFixed(2));\n    a.setAttribute('stroke-dashoffset',(-off).toFixed(2));\n    off+=x.v/tot*C;\n    legendRows[i].querySelector('.v').textContent=(x.v/tot*100).toFixed(1)+'%';\n    legendRows[i].title=x.n+' · '+fmt(x.v,2)+' QD';\n  });\n  $('dTot').textContent=fmt(tot,0);\n  $('eqTop').textContent=fmt(tot,2)+' QD';\n  if(!startEquity) startEquity=tot*(1-0.0142);\n  var pnl=tot-startEquity,pe=$('pnl');\n  pe.textContent=(pnl>=0?'+':'−')+fmt(Math.abs(pnl),2)+' · '+pct(pnl/startEquity);\n  pe.title='Profit and loss today (simulated)';\n  pe.className='pnl '+(pnl>=0?'up':'down');\n}\nfunction hl(){\n  arcs.forEach(function(a,i){a.classList.toggle('dim',hoverSeg>=0&&i!==hoverSeg);a.setAttribute('stroke-width',i===hoverSeg?'20':'16');});\n  legendRows.forEach(function(li,i){li.classList.toggle('hl',i===hoverSeg);});\n}\n\n/* ——— order ticket ——— */\nvar otype='limit';\nvar F={\n  buy:{price:$('fbPrice'),amt:$('fbAmt'),pct:$('fbPct'),tot:$('fbTot'),err:$('fbErr'),pf:$('fbPriceF'),af:$('fbAmtF')},\n  sell:{price:$('fsPrice'),amt:$('fsAmt'),pct:$('fsPct'),tot:$('fsTot'),err:$('fsErr'),pf:$('fsPriceF'),af:$('fsAmtF')}\n};\nfunction num(v){v=String(v).replace(/,/g,'').trim();if(v==='') return NaN;var n=Number(v);return isFinite(n)?n:NaN;}\nfunction effPrice(side){var m=INST[sel];return otype==='market'?m.price:num(F[side].price.value);}\nfunction paintAvail(){\n  var m=INST[sel];\n  $('availBuy').textContent=fmt(cash,2)+' QD';\n  $('availSell').textContent=fmt(m.hold,m.hold<10?4:3)+' '+m.sym;\n}\nfunction resetForms(){\n  var m=INST[sel];\n  ['buy','sell'].forEach(function(s){\n    var f=F[s];\n    f.price.value=otype==='market'?'Market':m.price.toFixed(m.dp);\n    f.price.disabled=otype==='market';\n    f.amt.value='';f.tot.value='';f.pct.value=0;setPct(f.pct);f.err.textContent='';\n    f.pf.classList.remove('bad');f.af.classList.remove('bad');\n  });\n  paintAvail();\n}\nfunction setPct(el){el.style.setProperty('--p',el.value+'%');}\nfunction recalc(side,from){\n  var m=INST[sel],f=F[side],p=effPrice(side);\n  if(from==='pct'){\n    var fr=+f.pct.value/100;\n    if(side==='buy'){var tot=cash*fr;f.tot.value=tot?tot.toFixed(2):'';f.amt.value=p>0&&tot?(tot/p).toFixed(4):'';}\n    else{var a=m.hold*fr;f.amt.value=a?a.toFixed(4):'';f.tot.value=p>0&&a?(a*p).toFixed(2):'';}\n  }else if(from==='tot'){\n    var t=num(f.tot.value);f.amt.value=p>0&&t>0?(t/p).toFixed(4):'';\n    syncPct(side);\n  }else{\n    var am=num(f.amt.value);f.tot.value=p>0&&am>0?(am*p).toFixed(2):'';\n    syncPct(side);\n  }\n  setPct(f.pct);\n  f.err.textContent='';f.pf.classList.remove('bad');f.af.classList.remove('bad');\n}\nfunction syncPct(side){\n  var m=INST[sel],f=F[side],am=num(f.amt.value),p=effPrice(side);\n  var v=side==='buy'?(cash>0&&am>0&&p>0?am*p/cash*100:0):(m.hold>0&&am>0?am/m.hold*100:0);\n  f.pct.value=clamp(Math.round(v),0,100);\n}\n['buy','sell'].forEach(function(side){\n  var f=F[side];\n  f.pct.addEventListener('input',function(){recalc(side,'pct');});\n  f.amt.addEventListener('input',function(){recalc(side,'amt');});\n  f.tot.addEventListener('input',function(){recalc(side,'tot');});\n  f.price.addEventListener('input',function(){recalc(side,'amt');});\n});\nArray.prototype.forEach.call(document.querySelectorAll('[data-stp]'),function(b){\n  b.addEventListener('click',function(){\n    if(otype==='market') return;\n    var m=INST[sel],inp=$(b.getAttribute('data-stp')),v=num(inp.value);\n    if(!(v>0)) v=m.price;\n    inp.value=(Math.round(v/m.step)*m.step+(+b.getAttribute('data-d'))*m.step).toFixed(m.dp);\n    recalc(inp.id==='fbPrice'?'buy':'sell','amt');\n  });\n});\nArray.prototype.forEach.call(document.querySelectorAll('[data-ot]'),function(b){\n  b.addEventListener('click',function(){\n    otype=b.getAttribute('data-ot');\n    Array.prototype.forEach.call(document.querySelectorAll('[data-ot]'),function(o){o.setAttribute('aria-pressed',String(o===b));});\n    resetForms();\n  });\n});\nfunction setPrice(p){\n  if(otype==='market'){otype='limit';Array.prototype.forEach.call(document.querySelectorAll('[data-ot]'),function(o){o.setAttribute('aria-pressed',String(o.getAttribute('data-ot')==='limit'));});resetForms();}\n  var m=INST[sel];\n  F.buy.price.value=p.toFixed(m.dp);F.sell.price.value=p.toFixed(m.dp);\n  recalc('buy','amt');recalc('sell','amt');\n  if(isMobile()) showPanel('p-ticket');\n}\nfunction validate(side){\n  var m=INST[sel],f=F[side],p=effPrice(side),a=num(f.amt.value);\n  f.pf.classList.remove('bad');f.af.classList.remove('bad');\n  if(otype==='limit'){\n    if(!(p>0)){f.pf.classList.add('bad');return 'Enter a valid price.';}\n    if(Math.abs(p/m.price-1)>.1){f.pf.classList.add('bad');return 'Limit price must be within ±10% of the last price.';}\n  }\n  if(!(a>0)){f.af.classList.add('bad');return 'Enter an amount greater than zero.';}\n  var tot=a*p;\n  if(tot<10){f.af.classList.add('bad');return 'Minimum order is 10.00 QD.';}\n  if(side==='buy'&&tot>cash+1e-6){f.af.classList.add('bad');return 'Insufficient QD: this order needs '+fmt(tot,2)+'.';}\n  if(side==='sell'&&a>m.hold+1e-9){f.af.classList.add('bad');return 'You hold only '+fmt(m.hold,4)+' '+m.sym+'.';}\n  return '';\n}\nfunction submit(side,e){\n  e.preventDefault();\n  var f=F[side],err=validate(side);\n  f.err.textContent=err;\n  if(err){\n    var el=f.af.classList.contains('bad')?f.amt:f.price;\n    if(el&&!el.disabled) el.focus();\n    return;\n  }\n  var m=INST[sel],p=effPrice(side),a=num(f.amt.value),tot=a*p;\n  if(side==='buy'){cash-=tot;m.hold+=a;}else{cash+=tot;m.hold-=a;if(m.hold<1e-9) m.hold=0;}\n  addTrade(p,a,side==='buy'?1:-1,true);\n  toast(side,(side==='buy'?'Bought ':'Sold ')+fmt(a,4)+' '+m.sym,\n    (otype==='market'?'Market':'Limit')+' order filled at <span class=\"mono\">'+fmt(p,m.dp)+'</span> · total <span class=\"mono\">'+fmt(tot,2)+' QD</span> <em style=\"color:#626c78;font-style:normal\">(simulated)</em>');\n  paintDonut(true);resetForms();\n}\n$('fBuy').addEventListener('submit',function(e){submit('buy',e);});\n$('fSell').addEventListener('submit',function(e){submit('sell',e);});\nvar toasts=$('toasts');\nfunction toast(side,title,body){\n  var t=document.createElement('div');t.className='toast '+side;t.setAttribute('role','status');\n  t.innerHTML='<b>'+title+'</b><p>'+body+'</p><i aria-hidden=\"true\"></i>';\n  toasts.appendChild(t);\n  setTimeout(function(){t.classList.add('out');setTimeout(function(){t.remove();},320);},4200);\n  while(toasts.children.length>4) toasts.removeChild(toasts.firstChild);\n}\n\n/* ——— mobile tabs ——— */\nvar mq=window.matchMedia('(max-width:760px)');\nfunction isMobile(){return mq.matches;}\nfunction showPanel(id){\n  Array.prototype.forEach.call(document.querySelectorAll('.panel'),function(p){p.classList.toggle('m-on',p.id===id);});\n  Array.prototype.forEach.call(document.querySelectorAll('#mtabs button'),function(b){b.setAttribute('aria-pressed',String(b.getAttribute('data-p')===id));});\n  requestAnimationFrame(function(){sizeChart();layoutBook();});\n}\n$('mtabs').addEventListener('click',function(e){var b=e.target.closest('button');if(b) showPanel(b.getAttribute('data-p'));});\n\n/* ——— clock ——— */\nfunction clock(){var d=new Date();$('clock').textContent=('0'+d.getUTCHours()).slice(-2)+':'+('0'+d.getUTCMinutes()).slice(-2)+':'+('0'+d.getUTCSeconds()).slice(-2)+' UTC';}\nsetInterval(clock,1000);clock();\n\n/* ——— market loop ——— */\nvar nextTick=0,nextBook=0,portT=0;\nfunction marketTick(){\n  // main instrument: price step + a burst of prints\n  var m=INST[sel];\n  var d=stepPrice(m);\n  var n=1+Math.floor(R()*3*(m.sig/m.vol));\n  var vol=0;\n  for(var k=0;k<Math.min(n,5);k++){\n    var sz=Math.exp(gauss(R))*(900/m.p)*(m.sig/m.vol);\n    vol+=sz;\n    addTrade(m.price+(R()<.5?0:(d>=0?-1:1)*m.step),sz,d>0?1:d<0?-1:(R()<.5?1:-1),false);\n  }\n  m.vol24+=vol;\n  liveCandle(m.price,vol);\n  paintHead(d>0?1:d<0?-1:0);\n  paintInst(sel,d>0?1:d<0?-1:0);\n  // others drift too\n  INST.forEach(function(o,i){\n    if(i===sel||R()<.45) return;\n    var dd=stepPrice(o);paintInst(i,dd>0?1:dd<0?-1:0);\n  });\n}\nvar last=performance.now();\nfunction loop(now){\n  var dt=now-last;last=now;\n  if(now>=nextTick){marketTick();nextTick=now+260+R()*420;}\n  if(now>=nextBook){jiggleBook();renderBook(false);nextBook=now+320;}\n  if(now>=portT){paintDonut(false);paintAvail();portT=now+1500;}\n  // ease the view\n  var k=1-Math.exp(-dt/90);\n  if(Math.abs(view.tBarW-view.barW)>.001||Math.abs(view.tEnd-view.end)>.001){\n    view.barW+=(view.tBarW-view.barW)*k;view.end+=(view.tEnd-view.end)*k;chartDirty=true;\n  }\n  if(chartDirty){chartDirty=false;drawChart();}\n  requestAnimationFrame(loop);\n}\n\n/* ——— boot ——— */\nbuildWatch();\nbuildDonut();\nsizeChart();\nselectInst(0);\nlayoutBook();\npaintAvail();\nvar ro=window.ResizeObserver?new ResizeObserver(function(){sizeChart();}):null;\nif(ro) ro.observe(box);\nvar rT=0;\nwindow.addEventListener('resize',function(){\n  sizeChart();\n  clearTimeout(rT);rT=setTimeout(function(){layoutBook();if(!isMobile()) Array.prototype.forEach.call(document.querySelectorAll('.panel'),function(p){p.classList.remove('m-on');});else if(!document.querySelector('.panel.m-on')) showPanel('p-chart');},120);\n});\nif(!isMobile()) Array.prototype.forEach.call(document.querySelectorAll('.panel'),function(p){p.classList.remove('m-on');});\nrequestAnimationFrame(function(t){last=t;nextTick=t+400;nextBook=t+300;requestAnimationFrame(loop);});\n})();\n</script>\n</body>\n</html>\n";
